517	import com.fasterxml.jackson.annotation.JsonProperty;
518	import org.springframework.beans.factory.annotation.Value;
519	import org.springframework.stereotype.Service;
520	import org.springframework.web.client.RestClient;
521	
522	import java.math.BigDecimal;
523	import java.math.RoundingMode;
524	import java.time.Duration;
525	
526	@Service
527	public class TransLogService {
528	
529	    private final String translogUrl;
530	    private final RestClient restClient;
531	
532	    public TransLogService(
533	            @Value("${translog.url}") String translogUrl,
534	            @Value("${translog.timeout.seconds}") int timeoutSeconds) {
535	        this.translogUrl = translogUrl;
536	        this.restClient = RestClient.builder()
537	                .baseUrl(translogUrl)
538	                .build();
539	    }
540	
541	    public QuoteResult getQuote(String zipCode, BigDecimal weightKg, String service) {
542	        try {
543	            int weightGrams = weightKg.multiply(new BigDecimal("1000")).intValue();
544	
545	            String url = String.format("/v2/quote?zip=%s&weight_g=%d&service=%s",
546	                    zipCode, weightGrams, service);
547	
548	            TransLogResponse response = restClient.get()
549	                    .uri(url)
550	                    .retrieve()
551	                    .body(TransLogResponse.class);
552	
553	            if (response == null) {
554	                return QuoteResult.unavailable();
555	            }
556	
557	            if (response.error != null) {
558	                if ("ZIP_NOT_SERVED".equals(response.error)) {
559	                    return QuoteResult.notServed();
560	                }
561	                return QuoteResult.unavailable();
562	            }
563	
564	            if (response.priceCents == null || response.etaHours == null) {
565	                return QuoteResult.unavailable();
566	            }
567	
568	            BigDecimal price = new BigDecimal(response.priceCents)
569	                    .divide(new BigDecimal("100"), 2, RoundingMode.HALF_EVEN);
570	
571	            int days = (int) Math.ceil(response.etaHours / 24.0);
572	
573	            return QuoteResult.success(price, days);
574	
575	        } catch (Exception e) {
576	            return QuoteResult.unavailable();
577	        }
578	    }
579	
580	    public static class QuoteResult {
581	        private final boolean available;
582	        private final boolean served;
583	        private final BigDecimal price;
584	        private final int days;
585	
586	        private QuoteResult(boolean available, boolean served, BigDecimal price, int days) {
587	            this.available = available;
588	            this.served = served;
589	            this.price = price;
590	            this.days = days;
591	        }
592	
593	        public static QuoteResult success(BigDecimal price, int days) {
594	            return new QuoteResult(true, true, price, days);
595	        }
596	
597	        public static QuoteResult notServed() {
598	            return new QuoteResult(true, false, null, 0);
599	        }
600	
601	        public static QuoteResult unavailable() {
602	            return new QuoteResult(false, false, null, 0);
603	        }
604	
605	        public boolean isAvailable() {
606	            return available;
607	        }
608	
609	        public boolean isServed() {
610	            return served;
611	        }
612	
613	        public BigDecimal getPrice() {
614	            return price;
615	        }
616	
617	        public int getDays() {
618	            return days;
619	        }
620	    }
621	
622	    private static class TransLogResponse {
623	        @JsonProperty("price_cents")
624	        private Integer priceCents;
625	
626	        @JsonProperty("eta_hours")
627	        private Integer etaHours;
628	
629	        private String error;
630	
631	        public Integer getPriceCents() {
632	            return priceCents;
633	        }
634	
635	        public void setPriceCents(Integer priceCents) {
636	            this.priceCents = priceCents;
637	        }
638	
639	        public Integer getEtaHours() {
640	            return etaHours;
641	        }
642	
643	        public void setEtaHours(Integer etaHours) {
644	            this.etaHours = etaHours;
645	        }
646	
647	        public String getError() {
648	            return error;
649	        }
650	
651	        public void setError(String error) {
652	            this.error = error;
653	        }
654	    }
655	}

