 77	
 78	@Service
 79	public class CheckoutCalculator {
 80	
 81	    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
 82	
 83	    private final ProductRepository productRepository;
 84	    private final OrderRepository orderRepository;
 85	    private final TransLogService transLogService;
 86	
 87	    public CheckoutCalculator(ProductRepository productRepository,
 88	                              OrderRepository orderRepository,
 89	                              TransLogService transLogService) {
 90	        this.productRepository = productRepository;
 91	        this.orderRepository = orderRepository;
 92	        this.transLogService = transLogService;
 93	    }
