 95	    public OrderSummary calculate(CheckoutRequest request) {
 96	        validateRequest(request);
 97	
 98	        Map<String, Product> productMap = loadProducts(request);
 99	        Map<String, Integer> itemQuantities = getItemQuantities(request);
100	
101	        validateProducts(productMap, itemQuantities);
102	
103	        BigDecimal productsSubtotal = calculateProductsSubtotal(productMap, itemQuantities);
104	
105	        ShippingInfo shippingInfo = calculateShipping(request, productMap, itemQuantities);
106	
107	        BigDecimal shippingCost = shippingInfo.cost;
108	        if (request.getClubTier() == ClubTier.GOLD && request.getShippingMethod() != ShippingMethod.COURIER) {
109	            shippingCost = ZERO;
110	        }
111	
112	        BigDecimal couponDiscount = calculateCouponDiscount(
113	                request, productsSubtotal, shippingCost, itemQuantities);
114	
115	        BigDecimal insurance = calculateInsurance(request.getRegion(), productsSubtotal);
116	
117	        BigDecimal orderTotal = productsSubtotal
118	                .subtract(couponDiscount)
119	                .add(shippingCost)
120	                .add(insurance);
121	
122	        PaymentInfo paymentInfo = calculatePayment(request, orderTotal);
123	
124	        BigDecimal nextPurchaseCredit = calculateClubCredit(request.getClubTier(), productsSubtotal);
125	
126	        boolean gift = shouldGiveGift(request.getClubTier(), request.getShippingMethod(), productsSubtotal);
127	
128	        OrderSummary summary = new OrderSummary();
129	        summary.setProductsSubtotal(productsSubtotal);
130	        summary.setCouponDiscount(couponDiscount);
131	        summary.setShippingCost(shippingCost);
132	        summary.setDeliveryDays(shippingInfo.days);
133	        summary.setInsurance(insurance);
134	        summary.setPaymentAdjustment(paymentInfo.adjustment);
135	        summary.setFinalTotal(paymentInfo.finalTotal);
136	        summary.setInstallments(paymentInfo.installments);
137	        summary.setInstallmentAmount(paymentInfo.installmentAmount);
138	        summary.setNextPurchaseCredit(nextPurchaseCredit);
139	        summary.setGift(gift);
140	
141	        return summary;
142	    }
143	
144	    private void validateRequest(CheckoutRequest request) {
145	        if (request.getCustomer() == null ||
146	            request.getCustomer().getCpf() == null ||
147	            request.getCustomer().getEmail() == null) {
148	            throw new BusinessException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
149	        }
150	
151	        if (request.getItems() == null || request.getItems().isEmpty()) {
152	            throw new BusinessException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
153	        }
154	
155	        Set<String> skus = new HashSet<>();
156	        for (var item : request.getItems()) {
157	            if (item.getSku() == null || item.getQuantity() == null || item.getQuantity() <= 0) {
158	                throw new BusinessException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
159	            }
160	            if (!skus.add(item.getSku())) {
161	                throw new BusinessException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
162	            }
163	        }
164	
165	        if (request.getClubTier() == null) {
166	            throw new BusinessException("INVALID_CLUB_TIER", HttpStatus.UNPROCESSABLE_ENTITY);
167	        }
168	
169	        if (request.getRegion() == null) {
170	            throw new BusinessException("INVALID_REGION", HttpStatus.UNPROCESSABLE_ENTITY);
171	        }
172	
173	        if (request.getZipCode() == null || !request.getZipCode().matches("\\d{8}")) {
174	            throw new BusinessException("INVALID_ZIP_CODE", HttpStatus.UNPROCESSABLE_ENTITY);
175	        }
176	
177	        if (request.getShippingMethod() == null) {
178	            throw new BusinessException("INVALID_SHIPPING_METHOD", HttpStatus.UNPROCESSABLE_ENTITY);
179	        }
180	
181	        if (request.getCoupon() != null) {
182	            try {
183	                Coupon.valueOf(request.getCoupon().name());
184	            } catch (IllegalArgumentException e) {
185	                throw new BusinessException("INVALID_COUPON", HttpStatus.UNPROCESSABLE_ENTITY);
186	            }
187	        }
188	
189	        if (request.getPaymentMethod() == null) {
190	            throw new BusinessException("INVALID_PAYMENT_METHOD", HttpStatus.UNPROCESSABLE_ENTITY);
191	        }
192	
193	        int installments = request.getInstallments() != null ? request.getInstallments() : 1;
194	        validateInstallments(request.getPaymentMethod(), installments);
195	    }
196	
197	    private void validateInstallments(PaymentMethod paymentMethod, int installments) {
198	        switch (paymentMethod) {
199	            case PIX, BANK_SLIP -> {
200	                if (installments != 1) {
201	                    throw new BusinessException("INVALID_INSTALLMENTS", HttpStatus.UNPROCESSABLE_ENTITY);
202	                }
203	            }
204	            case CREDIT_CARD -> {
205	                if (installments < 1 || installments > 12) {
206	                    throw new BusinessException("INVALID_INSTALLMENTS", HttpStatus.UNPROCESSABLE_ENTITY);
207	                }
208	            }
209	        }
210	    }
211	
212	    private Map<String, Product> loadProducts(CheckoutRequest request) {
213	        List<String> skus = request.getItems().stream()
214	                .map(CheckoutRequest.ItemRequest::getSku)
215	                .toList();
216	
217	        List<Product> products = productRepository.findAllById(skus);
218	
219	        if (products.size() != skus.size()) {
220	            throw new BusinessException("UNKNOWN_PRODUCT", HttpStatus.UNPROCESSABLE_ENTITY);
221	        }
222	
223	        Map<String, Product> map = new HashMap<>();
224	        for (Product p : products) {
225	            map.put(p.getSku(), p);
226	        }
227	        return map;
228	    }
229	
230	    private Map<String, Integer> getItemQuantities(CheckoutRequest request) {
231	        Map<String, Integer> map = new HashMap<>();
232	        for (var item : request.getItems()) {
233	            map.put(item.getSku(), item.getQuantity());
234	        }
235	        return map;
236	    }
237	
238	    private void validateProducts(Map<String, Product> productMap, Map<String, Integer> itemQuantities) {
239	        for (var entry : itemQuantities.entrySet()) {
240	            Product product = productMap.get(entry.getKey());
241	
242	            if (product.getDiscontinued()) {
243	                throw new BusinessException("PRODUCT_DISCONTINUED", HttpStatus.UNPROCESSABLE_ENTITY);
244	            }
245	
246	            if (product.getStock() < entry.getValue()) {
247	                throw new BusinessException("INSUFFICIENT_STOCK", HttpStatus.UNPROCESSABLE_ENTITY);
248	            }
249	        }
250	    }
251	
252	    private BigDecimal calculateProductsSubtotal(Map<String, Product> productMap,
253	                                                  Map<String, Integer> itemQuantities) {
254	        BigDecimal total = ZERO;
255	        for (var entry : itemQuantities.entrySet()) {
256	            Product product = productMap.get(entry.getKey());
257	            BigDecimal itemTotal = product.getPrice()
258	                    .multiply(new BigDecimal(entry.getValue()))
259	                    .setScale(2, RoundingMode.HALF_EVEN);
260	            total = total.add(itemTotal);
261	        }
262	        return total.setScale(2, RoundingMode.HALF_EVEN);
263	    }
264	
265	    private ShippingInfo calculateShipping(CheckoutRequest request,
266	                                           Map<String, Product> productMap,
267	                                           Map<String, Integer> itemQuantities) {
268	        BigDecimal totalWeight = ZERO;
269	        for (var entry : itemQuantities.entrySet()) {
270	            Product product = productMap.get(entry.getKey());
271	            BigDecimal itemWeight = product.getWeightKg().multiply(new BigDecimal(entry.getValue()));
272	            totalWeight = totalWeight.add(itemWeight);
273	        }
274	
275	        switch (request.getShippingMethod()) {
276	            case STORE_PICKUP -> {
277	                return new ShippingInfo(ZERO, 1);
278	            }
279	            case COURIER -> {
280	                if (totalWeight.compareTo(new BigDecimal("5.0")) > 0) {
281	                    throw new BusinessException("SHIPPING_METHOD_UNAVAILABLE", HttpStatus.UNPROCESSABLE_ENTITY);
282	                }
283	                return new ShippingInfo(new BigDecimal("18.00"), 0);
284	            }
285	            case ECONOMY, EXPRESS -> {
286	                String service = request.getShippingMethod() == ShippingMethod.ECONOMY ? "STD" : "EXP";
287	
288	                TransLogService.QuoteResult quote = transLogService.getQuote(
289	                        request.getZipCode(), totalWeight, service);
290	
291	                if (!quote.isAvailable()) {
292	                    throw new BusinessException("CARRIER_UNAVAILABLE", HttpStatus.SERVICE_UNAVAILABLE);
293	                }
294	
295	                if (!quote.isServed()) {
296	                    throw new BusinessException("SHIPPING_METHOD_UNAVAILABLE", HttpStatus.UNPROCESSABLE_ENTITY);
297	                }
298	
299	                int extraDays = getExtraDays(request.getRegion());
300	                return new ShippingInfo(quote.getPrice(), quote.getDays() + extraDays);
301	            }
302	            default -> throw new BusinessException("INVALID_SHIPPING_METHOD", HttpStatus.UNPROCESSABLE_ENTITY);
303	        }
304	    }
305	
306	    private int getExtraDays(Region region) {
307	        return switch (region) {
308	            case NORTH -> 3;
309	            case NORTHEAST -> 2;
310	            default -> 0;
311	        };
312	    }
313	
314	    private BigDecimal calculateCouponDiscount(CheckoutRequest request,
315	                                                BigDecimal productsSubtotal,
316	                                                BigDecimal shippingCost,
317	                                                Map<String, Integer> itemQuantities) {
318	        if (request.getCoupon() == null) {
319	            return ZERO;
320	        }
321	
322	        BigDecimal discount = switch (request.getCoupon()) {
323	            case WELCOME10 -> {
324	                if (!isFirstPurchase(request.getCustomer().getCpf())) {
325	                    throw new BusinessException("COUPON_NOT_APPLICABLE", HttpStatus.UNPROCESSABLE_ENTITY);
326	                }
327	                yield productsSubtotal.multiply(new BigDecimal("0.10"));
328	            }
329	            case MINUS50 -> {
330	                if (productsSubtotal.compareTo(new BigDecimal("300.00")) < 0) {
331	                    throw new BusinessException("COUPON_NOT_APPLICABLE", HttpStatus.UNPROCESSABLE_ENTITY);
332	                }
333	                yield new BigDecimal("50.00");
334	            }
335	            case FREESHIPPING -> {
336	                if (request.getShippingMethod() == ShippingMethod.STORE_PICKUP) {
337	                    throw new BusinessException("COUPON_NOT_APPLICABLE", HttpStatus.UNPROCESSABLE_ENTITY);
338	                }
339	                yield shippingCost;
340	            }
341	            case BUY3PAY2 -> {
342	                BigDecimal buy3pay2Discount = ZERO;
343	                for (var entry : itemQuantities.entrySet()) {
344	                    if (entry.getValue() >= 3) {
345	                        Product product = productRepository.findById(entry.getKey()).orElseThrow();
346	                        int freeItems = entry.getValue() / 3;
347	                        buy3pay2Discount = buy3pay2Discount.add(
348	                                product.getPrice().multiply(new BigDecimal(freeItems)));
349	                    }
350	                }
351	                yield buy3pay2Discount;
352	            }
353	        };
354	
355	        discount = discount.setScale(2, RoundingMode.HALF_EVEN);
356	
357	        BigDecimal maxDiscount = productsSubtotal.multiply(new BigDecimal("0.30"))
358	                .setScale(2, RoundingMode.HALF_EVEN);
359	
360	        if (discount.compareTo(maxDiscount) > 0) {
361	            discount = maxDiscount;
362	        }
363	
364	        return discount;
365	    }
366	
367	    private boolean isFirstPurchase(String cpf) {
368	        long paidOrders = orderRepository.countByCustomerCpfAndStatusIn(
369	                cpf, OrderStatus.PAID, OrderStatus.SHIPPED, OrderStatus.DELIVERED);
370	        return paidOrders == 0;
371	    }
372	
373	    private BigDecimal calculateInsurance(Region region, BigDecimal productsSubtotal) {
374	        BigDecimal rate;
375	        BigDecimal limit;
376	
377	        switch (region) {
378	            case SOUTHEAST, SOUTH -> {
379	                rate = new BigDecimal("0.01");
380	                limit = null;
381	            }
382	            case MIDWEST -> {
383	                rate = new BigDecimal("0.015");
384	                limit = null;
385	            }
386	            case NORTH -> {
387	                rate = new BigDecimal("0.025");
388	                limit = new BigDecimal("30.00");
389	            }
390	            case NORTHEAST -> {
391	                rate = new BigDecimal("0.02");
392	                limit = new BigDecimal("30.00");
393	            }
394	            default -> {
395	                rate = ZERO;
396	                limit = null;
397	            }
398	        }
399	
400	        BigDecimal insurance = productsSubtotal.multiply(rate).setScale(2, RoundingMode.HALF_EVEN);
401	
402	        if (limit != null && insurance.compareTo(limit) > 0) {
403	            insurance = limit;
404	        }
405	
406	        return insurance;
407	    }
408	
409	    private PaymentInfo calculatePayment(CheckoutRequest request, BigDecimal orderTotal) {
410	        int installments = request.getInstallments() != null ? request.getInstallments() : 1;
411	
412	        BigDecimal adjustment;
413	        BigDecimal finalTotal;
414	        BigDecimal installmentAmount;
415	
416	        switch (request.getPaymentMethod()) {
417	            case PIX -> {
418	                if (request.getCoupon() == null) {
419	                    BigDecimal discount = orderTotal.multiply(new BigDecimal("0.05"))
420	                            .setScale(2, RoundingMode.HALF_EVEN);
421	                    adjustment = discount.negate();
422	                    finalTotal = orderTotal.subtract(discount);
423	                } else {
424	                    adjustment = ZERO;
425	                    finalTotal = orderTotal;
426	                }
427	                installmentAmount = finalTotal;
428	            }
429	            case BANK_SLIP -> {
430	                if (orderTotal.compareTo(new BigDecimal("1000.00")) > 0) {
431	                    throw new BusinessException("PAYMENT_METHOD_UNAVAILABLE", HttpStatus.UNPROCESSABLE_ENTITY);
432	                }
433	                BigDecimal fee = new BigDecimal("3.49");
434	                adjustment = fee;
435	                finalTotal = orderTotal.add(fee);
436	                installmentAmount = finalTotal;
437	            }
438	            case CREDIT_CARD -> {
439	                if (installments <= 3) {
440	                    adjustment = ZERO;
441	                    finalTotal = orderTotal;
442	                    installmentAmount = finalTotal.divide(new BigDecimal(installments), 2, RoundingMode.HALF_EVEN);
443	                } else {
444	                    BigDecimal monthlyRate = new BigDecimal("0.0199");
445	                    BigDecimal onePlusRate = BigDecimal.ONE.add(monthlyRate);
446	                    BigDecimal factor = onePlusRate.pow(installments);
447	
448	                    installmentAmount = orderTotal.multiply(monthlyRate)
449	                            .divide(BigDecimal.ONE.subtract(BigDecimal.ONE.divide(factor, 10, RoundingMode.HALF_EVEN)),
450	                                    2, RoundingMode.HALF_EVEN);
451	
452	                    finalTotal = installmentAmount.multiply(new BigDecimal(installments));
453	                    adjustment = finalTotal.subtract(orderTotal);
454	                }
455	            }
456	            default -> throw new BusinessException("INVALID_PAYMENT_METHOD", HttpStatus.UNPROCESSABLE_ENTITY);
457	        }
458	
459	        return new PaymentInfo(adjustment, finalTotal, installments, installmentAmount);
460	    }
461	
462	    private BigDecimal calculateClubCredit(ClubTier tier, BigDecimal productsSubtotal) {
463	        BigDecimal rate = switch (tier) {
464	            case BRONZE -> ZERO;
465	            case SILVER -> new BigDecimal("0.02");
466	            case GOLD -> new BigDecimal("0.05");
467	        };
468	
469	        return productsSubtotal.multiply(rate).setScale(2, RoundingMode.HALF_EVEN);
470	    }
471	
472	    private boolean shouldGiveGift(ClubTier tier, ShippingMethod shippingMethod, BigDecimal productsSubtotal) {
473	        if (tier != ClubTier.GOLD) {
474	            return false;
475	        }
476	
477	        if (shippingMethod == ShippingMethod.COURIER) {
478	            return false;
479	        }
480	
481	        return productsSubtotal.compareTo(new BigDecimal("500.00")) > 0;
482	    }
483	
484	    public OrderSummary applyGoldBenefits(OrderSummary summary, ClubTier tier, ShippingMethod shippingMethod) {
485	        if (tier == ClubTier.GOLD && shippingMethod != ShippingMethod.COURIER) {
486	            summary.setShippingCost(ZERO);
487	        }
488	        return summary;
489	    }
490	
491	    private static class ShippingInfo {
492	        final BigDecimal cost;
493	        final int days;
494	
495	        ShippingInfo(BigDecimal cost, int days) {
496	            this.cost = cost;
497	            this.days = days;
498	        }
499	    }
500	
501	    private static class PaymentInfo {
502	        final BigDecimal adjustment;
503	        final BigDecimal finalTotal;
504	        final int installments;
505	        final BigDecimal installmentAmount;
506	
507	        PaymentInfo(BigDecimal adjustment, BigDecimal finalTotal, int installments, BigDecimal installmentAmount) {
508	            this.adjustment = adjustment;
509	            this.finalTotal = finalTotal;
510	            this.installments = installments;
511	            this.installmentAmount = installmentAmount;
512	        }
513	    }
514	}
