204	                    .orElseThrow(() -> new BusinessException("UNKNOWN_PRODUCT", HttpStatus.UNPROCESSABLE_ENTITY));
205	
206	            if (product.getStock() < item.getQuantity()) {
207	                throw new BusinessException("INSUFFICIENT_STOCK", HttpStatus.CONFLICT);
208	            }
209	
210	            product.setStock(product.getStock() - item.getQuantity());
211	            productsToUpdate.add(product);
212	        }
213	
214	        productRepository.saveAll(productsToUpdate);
215	    }
216	
217	    private void releaseStock(Order order) {
218	        for (OrderItem item : order.getItems()) {
219	            Product product = productRepository.findBySkuForUpdate(item.getSku())
220	                    .orElseThrow(() -> new BusinessException("UNKNOWN_PRODUCT", HttpStatus.UNPROCESSABLE_ENTITY));
221	
222	            product.setStock(product.getStock() + item.getQuantity());
223	            productRepository.save(product);
224	        }
225	    }
